module.exports = function toroman(input) {
  const parse = require('./parse.js');
  const romanNumerals = [
    { value: 1000, symbol: 'M' },
    { value: 900, symbol: 'CM' },
    { value: 500, symbol: 'D' },
    { value: 400, symbol: 'CD' },
    { value: 100, symbol: 'C' },
    { value: 90, symbol: 'XC' },
    { value: 50, symbol: 'L' },
    { value: 40, symbol: 'XL' },
    { value: 10, symbol: 'X' },
    { value: 9, symbol: 'IX' },
    { value: 5, symbol: 'V' },
    { value: 4, symbol: 'IV' },
    { value: 1, symbol: 'I' }
  ];

  let number = parse(input);
  let result = '';

  romanNumerals.forEach(function(roman) {
    while (number >= roman.value) {
      result += roman.symbol;
      number -= roman.value;
    }
  });

  return result;
};

module.exports = function fromroman(roman) {
  const romanNumerals = {
    M: 1000,
    CM: 900,
    D: 500,
    CD: 400,
    C: 100,
    XC: 90,
    L: 50,
    XL: 40,
    X: 10,
    IX: 9,
    V: 5,
    IV: 4,
    I: 1
  };

  let result = 0;
  let i = 0;

  while (i < roman.length) {
    const currentChar = roman[i];
    const nextChar = roman[i + 1];

